def containsDuplicate(nums):
    seen=set()
    for n in nums:
        if n in seen:return True
        seen.add(n)
    return False

def isAnagram(s,t):
    if len(s)!=len(t):return False
    counts={}
    for c in s:counts[c]=counts.get(c,0)+1
    for c in t:
        if counts.get(c,0)==0:return False
        counts[c]-=1
    return True

def firstUniqChar(s):
    counts={}
    for c in s:counts[c]=counts.get(c,0)+1
    for i,c in enumerate(s):
        if counts[c]==1:return i
    return -1

def canConstruct(ransomNote,magazine):
    counts={}
    for c in magazine:counts[c]=counts.get(c,0)+1
    for c in ransomNote:
        if counts.get(c,0)==0:return False
        counts[c]-=1
    return True

def pivotIndex(nums):
    total=sum(nums);left=0
    for i,n in enumerate(nums):
        if left==total-left-n:return i
        left+=n
    return -1

def isIsomorphic(s,t):
    forward={};backward={}
    for a,b in zip(s,t):
        if a in forward and forward[a]!=b:return False
        if b in backward and backward[b]!=a:return False
        forward[a]=b;backward[b]=a
    return True

def wordPattern(pattern,s):
    words=s.split()
    if len(pattern)!=len(words):return False
    forward={};backward={}
    for a,b in zip(pattern,words):
        if a in forward and forward[a]!=b:return False
        if b in backward and backward[b]!=a:return False
        forward[a]=b;backward[b]=a
    return True

def subarraySum(nums,k):
    counts={0:1};prefix=0;answer=0
    for n in nums:
        prefix+=n;answer+=counts.get(prefix-k,0)
        counts[prefix]=counts.get(prefix,0)+1
    return answer

def longestConsecutive(nums):
    values=set(nums);best=0
    for n in values:
        if n-1 not in values:
            end=n
            while end in values:end+=1
            best=max(best,end-n)
    return best

def isValidSudoku(board):
    seen=set()
    for r in range(9):
        for c in range(9):
            x=board[r][c]
            if x=='.':continue
            for key in [('r',r,x),('c',c,x),('b',r//3,c//3,x)]:
                if key in seen:return False
                seen.add(key)
    return True

def validPalindrome(s):
    left=0;right=len(s)-1
    while left<right:
        if s[left]!=s[right]:
            a=s[left+1:right+1];b=s[left:right]
            return a==a[::-1] or b==b[::-1]
        left+=1;right-=1
    return True

def reverseVowels(s):
    a=list(s);left=0;right=len(a)-1;vowels=set('aeiouAEIOU')
    while left<right:
        if a[left] not in vowels:left+=1;continue
        if a[right] not in vowels:right-=1;continue
        a[left],a[right]=a[right],a[left];left+=1;right-=1
    return ''.join(a)

def isSubsequence(s,t):
    i=0
    for c in t:
        if i<len(s) and s[i]==c:i+=1
    return i==len(s)

def numRescueBoats(people,limit):
    people=sorted(people);left=0;right=len(people)-1;boats=0
    while left<=right:
        if people[left]+people[right]<=limit:left+=1
        right-=1;boats+=1
    return boats

def longestMountain(arr):
    n=len(arr);i=0;best=0
    while i<n:
        start=i
        while i+1<n and arr[i]<arr[i+1]:i+=1
        peak=i
        while i+1<n and arr[i]>arr[i+1]:i+=1
        if start<peak<i:best=max(best,i-start+1)
        if i==start:i+=1
    return best

def trap(height):
    left=0;right=len(height)-1;left_max=right_max=water=0
    while left<=right:
        if left_max<=right_max:
            left_max=max(left_max,height[left]);water+=left_max-height[left];left+=1
        else:
            right_max=max(right_max,height[right]);water+=right_max-height[right];right-=1
    return water

def isValid(s):
    stack=[];pairs={')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{':stack.append(c)
        elif not stack or stack.pop()!=pairs[c]:return False
    return not stack

def removeDuplicates(s):
    stack=[]
    for c in s:
        if stack and stack[-1]==c:stack.pop()
        else:stack.append(c)
    return ''.join(stack)

def validateStackSequences(pushed,popped):
    stack=[];j=0
    for x in pushed:
        stack.append(x)
        while stack and j<len(popped) and stack[-1]==popped[j]:stack.pop();j+=1
    return j==len(popped)

def decodeString(s):
    stack=[];current='';count=0
    for c in s:
        if c.isdigit():count=count*10+int(c)
        elif c=='[':stack.append((current,count));current='';count=0
        elif c==']':prefix,repeats=stack.pop();current=prefix+current*repeats
        else:current+=c
    return current

def simplifyPath(path):
    stack=[]
    for component in path.split('/'):
        if component in ('','.'):continue
        if component=='..':
            if stack:stack.pop()
        else:stack.append(component)
    return '/'+ '/'.join(stack)

def asteroidCollision(asteroids):
    stack=[]
    for x in asteroids:
        alive=True
        while alive and x<0 and stack and stack[-1]>0:
            if stack[-1]<-x:stack.pop()
            elif stack[-1]==-x:stack.pop();alive=False
            else:alive=False
        if alive:stack.append(x)
    return stack

def search(nums,target):
    left=0;right=len(nums)-1
    while left<=right:
        mid=(left+right)//2
        if nums[mid]==target:return mid
        if nums[left]<=nums[mid]:
            if nums[left]<=target<nums[mid]:right=mid-1
            else:left=mid+1
        else:
            if nums[mid]<target<=nums[right]:left=mid+1
            else:right=mid-1
    return -1

def shipWithinDays(weights,days):
    left=max(weights);right=sum(weights)
    while left<right:
        mid=(left+right)//2;used=1;load=0
        for w in weights:
            if load+w>mid:used+=1;load=0
            load+=w
        if used<=days:right=mid
        else:left=mid+1
    return left

def maxVowels(s,k):
    vowels=set('aeiou');count=sum(c in vowels for c in s[:k]);best=count
    for right in range(k,len(s)):
        count+=(s[right] in vowels)-(s[right-k] in vowels);best=max(best,count)
    return best

def lengthOfLongestSubstring(s):
    last={};left=0;best=0
    for right,c in enumerate(s):
        left=max(left,last.get(c,-1)+1);last[c]=right;best=max(best,right-left+1)
    return best

def totalFruit(fruits):
    counts={};left=0;best=0
    for right,x in enumerate(fruits):
        counts[x]=counts.get(x,0)+1
        while len(counts)>2:
            old=fruits[left];counts[old]-=1;left+=1
            if counts[old]==0:del counts[old]
        best=max(best,right-left+1)
    return best

def minSubArrayLen(target,nums):
    left=total=0;best=len(nums)+1
    for right,n in enumerate(nums):
        total+=n
        while total>=target:
            best=min(best,right-left+1);total-=nums[left];left+=1
    return 0 if best==len(nums)+1 else best

def equalSubstring(s,t,maxCost):
    left=cost=best=0
    for right in range(len(s)):
        cost+=abs(ord(s[right])-ord(t[right]))
        while cost>maxCost:
            cost-=abs(ord(s[left])-ord(t[left]));left+=1
        best=max(best,right-left+1)
    return best

def maxSatisfied(customers,grumpy,minutes):
    base=sum(c for c,g in zip(customers,grumpy) if not g)
    gain=sum(customers[i]*grumpy[i] for i in range(minutes));best=gain
    for i in range(minutes,len(customers)):
        gain+=customers[i]*grumpy[i]-customers[i-minutes]*grumpy[i-minutes];best=max(best,gain)
    return base+best

