def lemonadeChange(bills):
    five = ten = 0
    for bill in bills:
        if bill == 5:
            five += 1
        elif bill == 10:
            five -= 1
            ten += 1
        elif ten and five:
            ten -= 1
            five -= 1
        else:
            five -= 3
        if five < 0:
            return False
    return True

def canPlaceFlowers(flowerbed, n):
    bed = list(flowerbed)
    for i in range(len(bed)):
        if bed[i] == 0 and (i == 0 or bed[i-1] == 0) and (i+1 == len(bed) or bed[i+1] == 0):
            bed[i] = 1
            n -= 1
    return n <= 0

def canJump(nums):
    reach = 0
    for i, jump in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i+jump)
    return True

def jump(nums):
    steps = end = farthest = 0
    for i in range(len(nums)-1):
        farthest = max(farthest, i+nums[i])
        if i == end:
            steps += 1
            end = farthest
    return steps

