def twoCitySchedCost(costs):
    ordered = sorted(costs, key=lambda c: c[0]-c[1])
    n = len(ordered)//2
    return sum(c[0] for c in ordered[:n]) + sum(c[1] for c in ordered[n:])

def candy(ratings):
    n = len(ratings)
    candies = [1]*n
    for i in range(1, n):
        if ratings[i] > ratings[i-1]:
            candies[i] = candies[i-1]+1
    for i in range(n-2, -1, -1):
        if ratings[i] > ratings[i+1]:
            candies[i] = max(candies[i], candies[i+1]+1)
    return sum(candies)

def eraseOverlapIntervals(intervals):
    end = float('-inf')
    removed = 0
    for start, finish in sorted(intervals, key=lambda x: x[1]):
        if start < end:
            removed += 1
        else:
            end = finish
    return removed

def intervalIntersection(firstList, secondList):
    i = j = 0
    answer = []
    while i < len(firstList) and j < len(secondList):
        low = max(firstList[i][0], secondList[j][0])
        high = min(firstList[i][1], secondList[j][1])
        if low <= high:
            answer.append([low, high])
        if firstList[i][1] < secondList[j][1]:
            i += 1
        else:
            j += 1
    return answer

def removeCoveredIntervals(intervals):
    remaining = 0
    end = -1
    for start, finish in sorted(intervals, key=lambda x: (x[0], -x[1])):
        if finish > end:
            remaining += 1
            end = finish
    return remaining

def carPooling(trips, capacity):
    events = []
    for passengers, start, end in trips:
        events.append((start, passengers))
        events.append((end, -passengers))
    load = 0
    for position, change in sorted(events):
        load += change
        if load > capacity:
            return False
    return True

def findLongestChain(pairs):
    end = float('-inf')
