def balanced_parens(n):
    answer = []
    def visit(text, opened, closed):
        if closed == n:
            answer.append(text)
            return
        if opened < n:
            visit(text+'(', opened+1, closed)
        if closed < opened:
            visit(text+')', opened, closed+1)
    visit('', 0, 0)
    return answer

def countArrangement(n):
    from functools import lru_cache
    @lru_cache(None)
    def visit(position, used):
        if position > n:
            return 1
        total = 0
        for value in range(1, n+1):
            bit = 1 << (value-1)
            if not used & bit and (value % position == 0 or position % value == 0):
                total += visit(position+1, used | bit)
        return total
    return visit(1, 0)

def makesquare(matchsticks):
    if len(matchsticks) < 4 or sum(matchsticks) % 4:
        return False
    target = sum(matchsticks)//4
    sticks = sorted(matchsticks, reverse=True)
    if sticks[0] > target:
        return False
    sides = [0]*4
    def place(index):
        if index == len(sticks):
            return True
        tried = set()
        for side in range(4):
            if sides[side] in tried or sides[side]+sticks[index] > target:
                continue
            tried.add(sides[side])
            sides[side] += sticks[index]
            if place(index+1):
                return True
            sides[side] -= sticks[index]
        return False
    return place(0)

def getMaximumGold(grid):
