        extra = 0
        for x, y in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
            if 0 <= x < rows and 0 <= y < cols and grid[x][y]:
                extra = max(extra, visit(x,y))
        grid[r][c] = value
        return value+extra
    return max([visit(r,c) for r in range(rows) for c in range(cols) if grid[r][c]] or [0])

