def maxUniqueSplit(s):
    used = set()
    best = 0
    def search(start):
        nonlocal best
        if len(used)+len(s)-start <= best:
            return
        if start == len(s):
            best = max(best, len(used))
            return
        for end in range(start+1, len(s)+1):
            piece = s[start:end]
            if piece not in used:
                used.add(piece)
                search(end)
                used.remove(piece)
    search(0)
    return best

def totalNQueens(n):
    full = (1 << n)-1
    def search(columns, left, right):
        if columns == full:
            return 1
        choices = full & ~(columns | left | right)
        count = 0
        while choices:
            bit = choices & -choices
            choices -= bit
            count += search(columns | bit, ((left | bit) << 1) & full, (right | bit) >> 1)
        return count
    return search(0, 0, 0)

