def findOrder(numCourses, prerequisites):
    import heapq
    adj=[[] for _ in range(numCourses)];degree=[0]*numCourses
    for course,required in prerequisites:
        adj[required].append(course);degree[course]+=1
    ready=[i for i,d in enumerate(degree) if d==0];heapq.heapify(ready);order=[]
    while ready:
        v=heapq.heappop(ready);order.append(v)
