def shortest(N, edgeList):
    import heapq
    adj=[[] for _ in range(N)]
    for u,v,w in edgeList:adj[u].append((v,w))
    dist=[float('inf')]*N;dist[0]=0;heap=[(0,0)]
    while heap:
        cost,u=heapq.heappop(heap)
        if cost!=dist[u]:continue
        if u==N-1:return cost
        for v,w in adj[u]:
            new=cost+w
            if new<dist[v]:dist[v]=new;heapq.heappush(heap,(new,v))
    return -1

