    base=998244353;
    def power(x, y):
        if(y==0):
            return 1
        t=power(x, y//2)
        t=(t*t)%base
        if(y%2):
            t=(t*x)%base
        return t;
    def inverse(x):
        return power(x, base-2)
    f=[1]
    iv=[1]
    for i in range(1, 5555):
        f.append((f[i-1]*i)%base)
        iv.append(inverse(f[i]))
    def C(n, k):
        return (f[n]*iv[k]*iv[n-k])%base
    def candy(n, k):
        # print(n, k)
        return C(n+k-1, k-1)
