        for i in range(0, k+1):
            t=n-x*i
            # print(i, C(k, i))
            if(t<0):
                break
            if(i%2):
                ans=(ans-C(k, i)*candy(t, k))%base
            else:
                ans=(ans+C(k, i)*candy(t, k))%base 
        return ans
    p, s, r= list(map(int, input().split()))
