                    vis[u] = 1
                    st.append(u)
                else:
                    ns = set()
                    fr = len(st)-1
                    to = u
                    while 1:
                        ns.add((st[fr], to))
                        if st[fr] == u and len(ns) > 1:
                            break
                        elif st[fr] == u:
                            ns.add((to, st[fr]))
                            break
                        to = st[fr]
                        fr -= 1
                    es = ns
                    cycle =True
                    break
            else:
                vis[v] = 2
                del st[-1]
