import sys

def determine_president_routes():
    MOD = 1000000181
    def addM(a,b):
        return (a+b)%MOD
    def mulM(a,b):
        return (a*b)%MOD
    def dijk(adj,n,s):
        dist = [10**18]*n
        ways = [0]*n
        frontier = []
        dist[s] = 0
        ways[s] = 1
        heappush(frontier,(0,s))
        while (len(frontier)>0):
            x = heappop(frontier)
            if x[0]!=dist[x[1]]:
                continue
            x = x[1]
            for (i,l) in adj[x]:
                if dist[x]+l<dist[i]:
                    dist[i] = dist[x]+l
                    ways[i] = ways[x]
                    heappush(frontier,(dist[i],i))
                elif dist[x]+l==dist[i]:
                    ways[i] = addM(ways[i],ways[x])
        return (dist,ways)
    n,m,s,t = map(int,sys.stdin.readline().split())
    s-=1
    t-=1
    adj = [[] for i in range(n)]
    jda = [[] for i in range(n)]
