TOKENIZER = re.compile(r'(R+|F+|L+)(\d*)')

def execute(code):

    pos, dirs = (0,0), deque([(0,1), (1,0), (0,-1), (-1,0)])
    seens = {pos}

    for act,n in TOKENIZER.findall(code):
